def c_sum(nums):
  sum = 0
  for num in nums:
    sum += num
  return sum

# %% ../nbs/02_sequences/06_cost-complexity.ipynb #86d25f31
def c_min(seq):
  #Iterator to walk over the sequence
  it = iter(seq)
  cmp = 0
  # Assume first element as min
  winner = next(it)
  # walk over rest to compare
  for val in it:
    cmp += 1
    if val < winner:
      winner = val
  return winner, cmp

