def c_max(seq):
  #Iterator to walk over the sequence
  it = iter(seq)
  cmp = 0
  # Assume first element as min
  winner = next(it)
  # walk over rest to compare
  for val in it:
    cmp+=1
    # if not out_of_order(winner,val):
    if not val < winner:
      winner = val
  return winner, cmp

# %% ../nbs/02_sequences/06_cost-complexity.ipynb #cddf3ade
def find_fraud_2sum(txns, T):
  cmp = 0
  l = len(txns)
  for t1 in txns:
    for t2 in txns:
      cmp += 1
      if t1.id != t2.id and t1.amount + t2.amount == T:
        return (t1,t2),(l,cmp)
  return (None,None),(l,cmp)


