def find_fraud_3sum(txns, T):
    cmp = 0
    l = len(txns)
    for t1 in txns:
        for t2 in txns:
            for t3 in txns:
                cmp += 1
                ids = {t1.id, t2.id, t3.id}
                if len(ids) == 3 and t1.amount + t2.amount + t3.amount == T:
                    return (t1, t2, t3), (l, cmp)
    return (None, None, None), (l, cmp)
